page Home "/" {
  meta title="Nimbus" description="Nimbus: rápido, simple y abierto."

  state n = 0
  ref statBox
  ref raf
  computed shown = String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ".")

  fn run() {
    let start = performance.now()
    let step = t => {
      let p = Math.min((t - start) / 2000, 1)
      let eased = 1 - Math.pow(1 - p, 3)
      n = Math.round(12000 * eased)
      if (p < 1) { raf = requestAnimationFrame(step) }
    }
    raf = requestAnimationFrame(step)
  }

  mount {
    let reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if reduce {
      n = 12000
      return
    }
    let started = false
    let io = new IntersectionObserver(entries => {
      if (!started && entries[0].isIntersecting) {
        started = true
        run()
        io.disconnect()
      }
    }, { threshold: 0.4 })
    io.observe(statBox)
    cleanup {
      io.disconnect()
      if (raf) { cancelAnimationFrame(raf) }
    }
  }

  column gap=12 pad=4 {
    column class="hero" align=center justify=center gap=4 {
      title "Nimbus" tag=h1 large animate=rise
      text "La nube que se siente liviana." large animate=rise delay=150
      button "Empezar" primary hover=grow animate=rise delay=300
    }

    grid cols=1 md:cols=3 gap=4 {
      card reveal pad=6 gap=2 align=center {
        title "Rápido"
        text "Respuestas en milisegundos, siempre."
      }
      card reveal pad=6 gap=2 align=center {
        title "Simple"
        text "Todo claro, sin configuraciones eternas."
      }
      card reveal pad=6 gap=2 align=center {
        title "Abierto"
        text "Código abierto y hecho con la comunidad."
      }
    }

    column ref=statBox align=center gap=1 pad=8 {
      title shown tag=div class="stat"
      text "usuarios" muted
    }
  }

  style {
    .hero {
      min-height: 70vh;
      text-align: center;
      padding: 48px 16px;
      border-radius: 16px;
      background: linear-gradient(120deg, #c7d2fe, #fbcfe8, #a5f3fc, #ddd6fe);
      background-size: 300% 300%;
      animation: drift 20s ease-in-out infinite;
      color: #1e1b4b;
    }
    .stat {
      font-size: 4rem;
      font-weight: 800;
      font-variant-numeric: tabular-nums;
    }
    @keyframes drift {
      0% { background-position: 0% 50%; }
      50% { background-position: 100% 50%; }
      100% { background-position: 0% 50%; }
    }
    @media (prefers-reduced-motion: reduce) {
      .hero { animation: none; }
    }
  }
}

