import { useEffect, useRef, useState } from "react";

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState<boolean>(() =>
    typeof window !== "undefined" && typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)").matches
      : false
  );

  useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  return reduced;
}

function useInView<T extends Element>(threshold = 0.2) {
  const ref = useRef<T | null>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setInView(true);
            obs.disconnect();
          }
        });
      },
      { threshold }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [threshold]);

  return { ref, inView };
}

interface CardData {
  title: string;
  text: string;
  icon: string;
}

const CARDS: CardData[] = [
  { title: "Rápido", text: "Carga en un instante, sin esperas ni vueltas.", icon: "⚡" },
  { title: "Simple", text: "Una interfaz clara que se entiende al primer vistazo.", icon: "✨" },
  { title: "Abierto", text: "Código abierto y transparente, hecho con la comunidad.", icon: "🌍" },
];

function FeatureCard({
  card,
  index,
  reduced,
}: {
  card: CardData;
  index: number;
  reduced: boolean;
}) {
  const { ref, inView } = useInView<HTMLDivElement>(0.25);
  const visible = reduced || inView;

  return (
    <div
      ref={ref}
      style={{
        transitionDelay: reduced ? "0ms" : `${index * 180}ms`,
      }}
      className={`rounded-2xl border border-white/10 bg-white/5 p-8 text-center shadow-xl backdrop-blur ${
        reduced ? "" : "transition-all duration-700 ease-out"
      } ${
        visible ? "translate-y-0 opacity-100" : "translate-y-10 opacity-0"
      }`}
    >
      <div className="mb-4 text-4xl" aria-hidden="true">
        {card.icon}
      </div>
      <h3 className="mb-2 text-2xl font-semibold text-white">{card.title}</h3>
      <p className="text-slate-300">{card.text}</p>
    </div>
  );
}

function Counter({ target, reduced }: { target: number; reduced: boolean }) {
  const { ref, inView } = useInView<HTMLDivElement>(0.4);
  const [value, setValue] = useState(0);

  useEffect(() => {
    if (!inView) return;
    if (reduced) {
      setValue(target);
      return;
    }
    const duration = 2000;
    let raf = 0;
    let start: number | null = null;
    const tick = (now: number) => {
      if (start === null) start = now;
      const progress = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(Math.round(eased * target));
      if (progress < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [inView, reduced, target]);

  const formatted = new Intl.NumberFormat("es-AR").format(value);

  return (
    <div ref={ref} className="text-center">
      <div
        className="bg-gradient-to-r from-sky-300 to-fuchsia-300 bg-clip-text text-6xl font-extrabold tabular-nums text-transparent sm:text-7xl"
        aria-label={`${new Intl.NumberFormat("es-AR").format(target)} más usuarios`}
      >
        <span aria-hidden="true">{formatted}+</span>
      </div>
      <p className="mt-3 text-lg text-slate-300">usuarios ya confían en Nimbus</p>
    </div>
  );
}

export default function App() {
  const reduced = usePrefersReducedMotion();

  return (
    <div className="min-h-screen bg-slate-950 text-white">
      <style>{`
        @keyframes nimbus-gradient {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
        .nimbus-animated-bg {
          background-size: 300% 300%;
          animation: nimbus-gradient 20s ease-in-out infinite;
        }
        @media (prefers-reduced-motion: reduce) {
          .nimbus-animated-bg { animation: none; }
        }
      `}</style>

      <header className="relative flex min-h-screen items-center justify-center overflow-hidden px-6">
        <div
          aria-hidden="true"
          className="nimbus-animated-bg absolute inset-0 bg-gradient-to-br from-indigo-700 via-fuchsia-600 to-sky-500 opacity-80"
        />
        <div
          aria-hidden="true"
          className="absolute inset-0 bg-gradient-to-b from-transparent via-slate-950/20 to-slate-950"
        />
        <div className="relative z-10 max-w-2xl text-center">
          <h1 className="text-6xl font-extrabold tracking-tight sm:text-8xl">Nimbus</h1>
          <p className="mx-auto mt-6 max-w-xl text-lg text-white/90 sm:text-xl">
            La forma más liviana de llevar tus ideas a la nube.
          </p>
          <button
            type="button"
            className={`mt-10 rounded-full bg-white px-10 py-4 text-lg font-semibold text-slate-900 shadow-lg focus:outline-none focus-visible:ring-4 focus-visible:ring-white/60 ${
              reduced
                ? ""
                : "transition-transform duration-300 ease-out hover:scale-110"
            }`}
          >
            Empezar
